// Shared visual language for the four learning workspace chapters.
function chapterArt(type){
 const drawings={
 roadmap:`<path class="art-route" d="M75 238C145 238 110 176 180 176S240 105 300 105 321 58 365 58"/><path d="M75 255v25m105-88v88m120-159v159m65-206v206" class="art-guide"/>${[[75,238],[180,176],[300,105],[365,58]].map(([x,y],i)=>`<circle cx="${x}" cy="${y}" r="${i===1?14:8}" class="art-node"/><circle cx="${x}" cy="${y}" r="${i===1?25:17}" class="art-halo"/>`).join('')}<path d="m355 43 10-13 10 13" class="art-route"/>`,
 explore:`<ellipse cx="235" cy="155" rx="135" ry="70" transform="rotate(-27 235 155)" class="art-orbit"/><ellipse cx="235" cy="155" rx="135" ry="70" transform="rotate(38 235 155)" class="art-orbit"/><circle cx="235" cy="155" r="91" class="art-guide"/><path d="m255 103-7 65-42 38 14-67Z" class="art-compass"/><path d="m255 103-35 36 28 29" class="art-route"/>${[[113,210],[349,102],[318,234],[157,61]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="5" class="art-node"/><circle cx="${x}" cy="${y}" r="13" class="art-halo"/>`).join('')}`,
 projects:`<path d="m105 218 128-64 128 64-128 64Z" class="art-slab art-slab-bottom"/><path d="m105 174 128-64 128 64-128 64Z" class="art-slab art-slab-middle"/><path d="m105 130 128-64 128 64-128 64Z" class="art-slab art-slab-top"/><path d="m197 131 23 13 45-25" class="art-route"/><path d="M105 130v88m256-88v88M233 194v88" class="art-guide"/><circle cx="361" cy="130" r="6" class="art-node"/>`,
 opportunities:`<path d="M155 272V113a78 78 0 0 1 156 0v159" class="art-portal"/><path d="M175 272V116a58 58 0 0 1 116 0v156" class="art-guide"/><path d="m107 287 78-48h98l78 48M155 272h156M185 239v-82m98 82v-82" class="art-guide"/><path d="m210 159 47-47m-32 0h32v32" class="art-route"/><path d="M233 282v17M193 287l-8 12m88-12 8 12" class="art-guide"/>`
 };
 return `<div class="chapter-art" aria-hidden="true"><div class="chapter-art-glow"></div><svg viewBox="0 0 460 320" fill="none"><path d="M25 280H435M45 304H415" class="art-guide"/>${drawings[type]}</svg><span class="art-coordinate">NEXTSTEP / ${({roadmap:'THE ASCENT',explore:'FIND YOUR NORTH',projects:'MADE BY YOU',opportunities:'POSSIBILITIES AHEAD'})[type]}</span></div>`;
}
function chapterHero(type,{kicker,title,description,tag,metric,label,action}){
 return `<section class="chapter-hero"><div class="chapter-copy"><div class="chapter-kicker"><span></span>${kicker}</div><h1>${title}</h1><p>${description}</p><div class="chapter-hero-actions">${action}<span class="chapter-context">${I(({roadmap:'route',explore:'graduation-cap',projects:'layers-3',opportunities:'telescope'})[type])}<span ${type==='explore'?'id="explore-hero-course"':''}>${tag}</span></span></div></div><div class="chapter-visual">${chapterArt(type)}<div class="chapter-counter"><strong ${type==='explore'?'id="explore-hero-count"':''}>${metric}</strong><span>${label}</span></div></div></section>`;
}
function chapterMethod(){return `<div class="chapter-method">${[['book-open','01','Learn the idea','Clear concepts, before the task'],['scan-eye','02','See it in action','A worked example to guide you'],['flag','03','Make it yours','Practise when you understand']].map(([ic,n,t,d])=>`<div><span class="method-icon">${I(ic)}</span><span><small>Step ${n}</small><strong>${t}</strong><p>${d}</p></span></div>`).join('')}</div>`}
